#include <fmt/format.h>
#include <cstring>
#include <vector>
#include <iostream>

int main() {
  // format string: "{:\xE0\x80\x80>" - fill char is 3-byte UTF-8, then '>'
  // The format string buffer is allocated separately and tight.
  std::vector<char> fmtbuf;
  fmtbuf.push_back('{');
  fmtbuf.push_back(':');
  fmtbuf.push_back((char)0xE0);
  fmtbuf.push_back((char)0x80);
  fmtbuf.push_back((char)0x80);
  fmtbuf.push_back('>');
  fmt::string_view fmtstr(fmtbuf.data(), fmtbuf.size());
  try {
    fmt::memory_buffer out;
    fmt::format_to(out, fmtstr, fmt::arg("x", 42));
    std::cout << "ok\n";
  } catch (std::exception& e) {
    std::cout << "exception: " << e.what() << "\n";
  }
  return 0;
}
EOF
